var totalNumbers = function(digits) {
    const s = new Set();
    const n = digits.length;
    for (let i = 0; i < n; i++) {
        if (digits[i] === 0) continue;
        for (let j = 0; j < n; j++) {
            if (i === j) continue;
            for (let k = 0; k < n; k++) {
                if (k === i || k === j) continue;
                if (digits[k] % 2 !== 0) continue;
                const num = digits[i] * 100 + digits[j] * 10 + digits[k];
                s.add(num);
            }
        }
    }
    return s.size;
};
